import java.lang.reflect.Method;
import org.jetbrains.annotations.NotNull;
import com.example.MessageBuilder;
import org.springframework.cache.interceptor.KeyGenerator;
import org.springframework.cache.interceptor.SimpleKey;

class Foo implements KeyGenerator {
    @NotNull @Override
    public Object generate(Object target, Method method, Object... params) {
        if (params.length < 2 ) {
            String errorMessage = MessageBuilder
                    .format("KeyGenerator assumes at least 2 parameter: {}",
                            params);
            throw new IllegalArgumentException(errorMessage);
        }
        String relationId = (String) params[0];
        String accountId = (String) params[1];
        return new SimpleKey(appName, ClassUtils.getUserClass(target.getClass()).getName(), relationId, accountId);
    }
}

import java.lang.reflect.Method;
import org.jetbrains.annotations.NotNull;
import org.springframework.cache.interceptor.KeyGenerator;
import org.springframework.cache.interceptor.SimpleKey;

class Foo implements KeyGenerator {
    @NotNull @Override
    public Object generate(Object target, Method method, Object... params) {
        return new SimpleKey(target.getClass().getName(), method.getName(), params);
    }
}

import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;
import com.example.MyKeyGenerator;
import com.example.MyCache;
import org.springframework.cache.interceptor.KeyGenerator;
import org.springframework.util.StringUtils;

class Foo implements KeyGenerator {
    @Override
    public Object generate(Object target, Method method, Object... params) {
        List<String> accParams = new ArrayList<>();
        for(Object o:params){
            if(o!=null) {
                accParams.add(o.toString()); // bad
            }
        }
        return MyKeyGenerator.generate(MyCache.MY_CACHE_NAME, target, method, accParams);
    }
}

class Bar implements KeyGenerator {
    @Override
    public Object generate(Object target, Method method, Object... params) {
        List<String> accParams = new ArrayList<>();
        for(Object o:params){
            if(o!=null) {
                accParams.add(((User)o).toString()); // good, cast
            }
        }
        return MyKeyGenerator.generate(MyCache.MY_CACHE_NAME, target, method, accParams);
    }
}

class Bee implements KeyGenerator {
    @Override
    public Object generate(Object target, Method method, Object... params) {
        List<String> accParams = new ArrayList<>();
        for(Object o:params){
            if(o!=null) {
                User u = (User)o;
                accParams.add(u.toString()); // good, casted
            }
        }
        return MyKeyGenerator.generate(MyCache.MY_CACHE_NAME, target, method, accParams);
    }
}
